def svg_reparto():
    """Barra de 70 minutos con las tres marcas: arranque, control de mitad y cierre."""
    aria = t("A 70-minute bar. Minutes 0 to 5: settling in. Minute 35: halfway check, you should be at question 17 or 18. Minutes 60 to 70: the last ten minutes for marked questions and for leaving nothing blank.",
             "Barra de 70 minutos. Minutos 0 a 5: arranque. Minuto 35: control de mitad, debería ir por la pregunta 17 o 18. Minutos 60 a 70: los últimos diez minutos, para las marcadas y para no dejar nada en blanco.")
    X = lambda m: 30 + m * 660 / 70
    s = [f'<svg class="diagrama" style="max-width:720px" viewBox="0 0 720 170" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg">',
         f'<rect x="{X(0)}" y="50" width="{X(70) - X(0)}" height="40" rx="8" fill="#f1eafa" stroke="#5e3591" stroke-width="2"/>',
         f'<rect x="{X(0)}" y="50" width="{X(5) - X(0)}" height="40" rx="8" fill="#c9b5e6"/>',
         f'<rect x="{X(60)}" y="50" width="{X(70) - X(60)}" height="40" rx="8" fill="#5e3591"/>',
         f'<line x1="{X(35)}" y1="38" x2="{X(35)}" y2="102" stroke="#c0582f" stroke-width="4"/>']
    for m in (0, 10, 20, 30, 40, 50, 60, 70):
        s.append(f'<text x="{X(m)}" y="118" text-anchor="middle" {F} font-size="13" fill="#3d4753">{m}</text>')
    s.append(f'<text x="{X(0)}" y="32" {F} font-size="14" font-weight="700" fill="#5e3591">{t("0–5: settling in", "0–5: arranque")}</text>')
    s.append(f'<text x="{X(35)}" y="26" text-anchor="middle" {F} font-size="14" font-weight="700" fill="#c0582f">{t("Minute 35: question 17–18", "Minuto 35: pregunta 17–18")}</text>')
    s.append(f'<text x="{X(70)}" y="32" text-anchor="end" {F} font-size="14" font-weight="700" fill="#5e3591">{t("60–70: review", "60–70: cierre")}</text>')
    s.append(f'<text x="360" y="146" text-anchor="middle" {F} font-size="14" fill="#1a2330">{t("Minutes. About 2 per question on average; the first question of each scenario costs more.", "Minutos. Unos 2 por pregunta de media; la primera de cada escenario cuesta más.")}</text>')
    s.append(f'<text x="360" y="164" text-anchor="middle" {F} font-size="13" fill="#3d4753">{t("At question 12 at minute 35: speed up. At question 24: slow down and check.", "En la 12 al minuto 35: acelere. En la 24: no corra, revise.")}</text>')
    s.append("</svg>")
    return "".join(s)


