def clasif_errores():
    G = [t("Content", "De contenido"), t("Skill", "De destreza"), t("Question wording", "De enunciado"), t("Time", "De tiempo")]
    PI = [t("Did you simply not know the fact or the concept?", "¿Simplemente no sabía el dato o el concepto?"), t("Did you know the content but misread the source, graph, or argument?", "¿Sabía el contenido pero leyó mal la fuente, la gráfica o el argumento?"),
          t("Did you know the answer but answer something else?", "¿Sabía la respuesta pero contestó otra cosa?"), t("Was the clock the problem?", "¿El problema fue el reloj?")]
    def item(tit, piezas):
        return {"titulo": tit, "intro": t("On the test you would drag each situation into its box. Here, choose the box from the list.", "En el examen arrastraría cada situación a su casilla. Aquí, elija la casilla en la lista."), "grupos": G, "etiqueta": t("This mistake is…", "Este error es…"),
                "piezas": [{"t": a, "v": v, "pista": PI[v]} for a, v in piezas]}
