def completar():
    rnd = random.Random(831)
    out = []
    fmt = lambda x: format(D(x).normalize(), "f")
    for n in range(40):
        k = n % 4
        if k == 0:
            a = D(rnd.choice(["3.2", "4.5", "5.1", "6.8", "8.4", "9.7"])); b = a + D(rnd.choice(["2.3", "4.6", "7.5", "10.2", "12.8", "15.4"]))
            r = b - a; enun = t(f"Unemployment went from {fmt(a)}% to {fmt(b)}%. By how many <strong>percentage points</strong> did it rise?", f"El desempleo pasó del {fmt(a)} % al {fmt(b)} %. ¿En cuántos <strong>puntos porcentuales</strong> subió?")
            exp = t(f"{fmt(b)} − {fmt(a)} = {fmt(r)} points.", f"{fmt(b)} − {fmt(a)} = {fmt(r)} puntos.")
        elif k == 1:
            p = rnd.choice([20, 25, 40, 50, 80, 120, 200]); A = rnd.choice([2, 4, 5, 8, 10]); pop = p * A * 1000
            r = D(p); enun = t(f"A county has {pop:,} people and an area of {A * 1000:,} square miles. What is its population density, in <strong>people per square mile</strong>?", f"Un condado tiene {pop:,} habitantes y una superficie de {A * 1000:,} millas cuadradas. ¿Cuál es su densidad de población, en <strong>habitantes por milla cuadrada</strong>?")
            exp = t(f"{pop:,} ÷ {A * 1000:,} = {p}.", f"{pop:,} ÷ {A * 1000:,} = {p}.")
        elif k == 2:
            tot = rnd.choice([40, 50, 80, 120, 200, 250, 400]); pc = rnd.choice([10, 15, 20, 25, 30, 40, 45, 60])
            r = D(tot) * pc / 100; enun = t(f"In a precinct, {tot} people voted and {pc}% chose Candidate A. How many <strong>votes</strong> did Candidate A get?", f"En un distrito electoral votaron {tot} personas y el {pc} % eligió al candidato A. ¿Cuántos <strong>votos</strong> recibió el candidato A?")
            exp = t(f"{tot} × {pc} ÷ 100 = {fmt(r)}.", f"{tot} × {pc} ÷ 100 = {fmt(r)}.")
        else:
            vals = [rnd.choice([18, 20, 22, 24, 25, 26, 28, 30, 32, 35]) for _ in range(4)]
            r = D(sum(vals)) / 4; enun = t(f"Four neighborhoods have median rents (in hundreds of dollars) of {', '.join(map(str, vals))}. What is the mean of these four values, in <strong>hundreds of dollars</strong>?", f"Cuatro barrios tienen alquileres medianos (en cientos de dólares) de {', '.join(map(str, vals))}. ¿Cuál es la media de estos cuatro valores, en <strong>cientos de dólares</strong>?")
            exp = t(f"({' + '.join(map(str, vals))}) ÷ 4 = {sum(vals)} ÷ 4 = {fmt(r)}.", f"({' + '.join(map(str, vals))}) ÷ 4 = {sum(vals)} ÷ 4 = {fmt(r)}.")
        if r != r.quantize(D("0.01")):
            continue
        out.append({"enun": f"<p>{enun}</p>", "r": fmt(r), "exp": exp})
    return out


# ---- punto en una imagen
def svg_ramas():
    cajas = [("L", 20, t("Legislative", "Legislativo"), t("Congress", "Congreso")), ("E", 250, t("Executive", "Ejecutivo"), t("President", "Presidente")), ("J", 480, t("Judicial", "Judicial"), t("Courts", "Tribunales"))]
    z = "".join(f'<rect data-z="{k}" data-l="{a}" x="{x}" y="40" width="200" height="110" rx="12" fill="#e8eaf6" stroke="#283593" stroke-width="3"/>'
                f'<text x="{x + 100}" y="88" text-anchor="middle" {F} font-size="18" font-weight="700" fill="#283593" pointer-events="none">{a}</text>'
                f'<text x="{x + 100}" y="116" text-anchor="middle" {F} font-size="15" fill="#1a2330" pointer-events="none">{b}</text>' for k, x, a, b in cajas)
    return ('<svg viewBox="0 0 700 170" style="width:100%;max-width:640px;height:auto" role="group" aria-label="' + t("Three boxes for the three branches of the federal government: legislative (Congress), executive (President), and judicial (courts).", "Tres cajas para las tres ramas del gobierno federal: legislativa (Congreso), ejecutiva (presidente) y judicial (tribunales).") + '" xmlns="http://www.w3.org/2000/svg">' + z + '</svg>')


def svg_paro():
    datos = [("1929", 3.2), ("1931", 15.9), ("1933", 24.9), ("1935", 20.1), ("1937", 14.3), ("1939", 17.2)]
    base, alto, x0, bw = 230, 180 / 30, 70, 80
    g = [f'<line x1="{x0 - 10}" y1="{base}" x2="{x0 + 6 * 95}" y2="{base}" stroke="#1a2330" stroke-width="2"/>', f'<line x1="{x0 - 10}" y1="40" x2="{x0 - 10}" y2="{base}" stroke="#1a2330" stroke-width="2"/>']
    for v in (0, 10, 20, 30):
        g.append(f'<text x="{x0 - 16}" y="{base - v * alto + 5}" text-anchor="end" {F} font-size="13" fill="#3d4753">{v}%</text>')
    for i, (a, v) in enumerate(datos):
        x = x0 + i * 95
        g.append(f'<rect data-z="{a}" data-l="{a}: {v}%" x="{x}" y="{base - v * alto:.1f}" width="{bw}" height="{v * alto:.1f}" fill="#5b8def" stroke="#1e3a8a" stroke-width="2"/>'
                 f'<text x="{x + bw / 2}" y="{base - v * alto - 6:.1f}" text-anchor="middle" {F} font-size="13" font-weight="700" fill="#1e3a8a" pointer-events="none">{v}</text>'
                 f'<text x="{x + bw / 2}" y="{base + 20}" text-anchor="middle" {F} font-size="14" fill="#1a2330" pointer-events="none">{a}</text>')
    g.append(f'<text x="350" y="275" text-anchor="middle" {F} font-size="14" font-weight="700" fill="#1a2330">{t("U.S. unemployment rate (%)", "Tasa de desempleo de los EE. UU. (%)")}</text>')
    return ('<svg viewBox="0 0 680 290" style="width:100%;max-width:640px;height:auto" role="group" aria-label="' + t("Bar graph of U.S. unemployment: 1929, 3.2%; 1931, 15.9%; 1933, 24.9%; 1935, 20.1%; 1937, 14.3%; 1939, 17.2%.", "Gráfica de barras del desempleo de los EE. UU.: 1929, 3.2 %; 1931, 15.9 %; 1933, 24.9 %; 1935, 20.1 %; 1937, 14.3 %; 1939, 17.2 %.") + '" xmlns="http://www.w3.org/2000/svg">' + "".join(g) + '</svg>')


